// Teams-Bote: Nachricht an eine Kollegin oder einen Kollegen, im Namen der
// fragenden Person, ueber die Teams-Bruecke. Der erste Kanal, ueber den Rupert
// Dritten schreibt (der Mail-Skill versendet bewusst nie). Deshalb:
//   - zweistufig: erster Aufruf liefert Vorschau und Code, gesendet wird erst
//     beim zweiten Aufruf mit dem Code, derselbe Aufrufer, zehn Minuten gueltig
//   - begrenzt: 1000 Zeichen, 5 Nachrichten je Person und Stunde
//   - nur an Personen aus der eigenen Datenbank, die Rupert in Teams kennen
//   - Absenderzeile, damit die Empfaengerin weiss, von wem es kommt
// Das Feld caller setzt der MCP-Client des Agenten; Sub-Agenten und
// Hintergrundlaeufe schicken es leer und werden abgewiesen.

const input = { ...$input.first().json };
for (const _k of Object.keys(input)) { if (input[_k] === '' || input[_k] === null) delete input[_k]; }
const action = input.action || '';
const caller = String(input.caller || '').trim();

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const BRIDGE_URL = '{{BRIDGE_URL}}';
const BRIDGE_SECRET = '{{BRIDGE_SECRET}}';
const pg = { apikey: SUPABASE_KEY, Authorization: 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };
function fail(msg) { return [{ json: { error: msg } }]; }
async function get(path) { return helpers.httpRequest({ method: 'GET', url: SUPABASE_URL + path, headers: pg, json: true }); }
const normName = s => String(s || '').toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .replace(/[,.;()]/g, ' ').split(/\s+/).filter(w => w.length > 1);

if (action !== 'send_teams_message') return fail('Unbekannte Aktion "' + action + '". Moeglich ist: send_teams_message.');
if (!caller) return fail('Kein Nutzerbezug vorhanden. Teams-Nachrichten gehen nur im Namen einer angemeldeten Person, nicht aus einem Hintergrundlauf oder einem Sub-Agenten.');
const to = String(input.to || '').trim();
const text = String(input.text || '').trim();
const code = String(input.code || '').trim();
if (!to) return fail('Parameter "to" ist noetig: Name oder E-Mail-Adresse der Person.');
if (!text) return fail('Parameter "text" ist noetig.');
if (text.length > 1000) return fail('Hoechstens 1000 Zeichen je Nachricht, diese hat ' + text.length + '.');

try {
  let absender = caller;
  try {
    const sp = await get('/rest/v1/user_profiles?user_id=eq.' + encodeURIComponent(caller) + '&select=display_name,name');
    if (Array.isArray(sp) && sp[0]) absender = sp[0].display_name || sp[0].name || caller;
  } catch (e) {}

  // Empfaenger nur aus der eigenen Datenbank: Web-Profile mit Verknuepfung zum
  // Entra-Schluessel, oder Profile, die direkt unter dem Entra-Schluessel liegen.
  const maps = await get('/rest/v1/user_identity_map?select=legacy_key,entra_key,upn');
  const profile = await get('/rest/v1/user_profiles?select=user_id,display_name');
  const entraVon = {}; const upnVon = {};
  for (const m of (Array.isArray(maps) ? maps : [])) { entraVon[m.legacy_key] = m.entra_key; if (m.upn) upnVon[m.legacy_key] = m.upn; }
  const kandidaten = (Array.isArray(profile) ? profile : []).filter(p => p.display_name).map(p => ({
    key: p.user_id, name: p.display_name,
    entra: p.user_id.startsWith('entra:') ? p.user_id : (entraVon[p.user_id] || null),
    upn: upnVon[p.user_id] || null
  }));
  let treffer;
  if (to.includes('@')) {
    treffer = kandidaten.filter(k => k.upn && k.upn.toLowerCase() === to.toLowerCase());
  } else {
    const w = new Set(normName(to));
    treffer = kandidaten.filter(k => { const n = normName(k.name); return n.length > 0 && w.size > 0 && (n.every(x => w.has(x)) || [...w].every(x => n.includes(x))); });
  }
  const gesehen = new Set();
  treffer = treffer.filter(k => { const id = k.entra || k.key; if (gesehen.has(id)) return false; gesehen.add(id); return true; });
  // Mehrere Treffer: erst der exakte Name, dann die Personen, die in Teams
  // erreichbar sind (Web- und Telegram-Profil derselben Person zaehlen so einmal).
  if (treffer.length > 1) {
    const exakt = treffer.filter(k => normName(k.name).join(' ') === normName(to).join(' '));
    const erreichbar = (exakt.length ? exakt : treffer).filter(k => k.entra);
    if (exakt.length === 1) treffer = exakt;
    else if (erreichbar.length === 1) treffer = erreichbar;
  }
  if (treffer.length === 0) return fail('Ich kenne niemanden mit "' + to + '". Bitte den vollen Namen oder die E-Mail-Adresse angeben.');
  if (treffer.length > 1) return fail('Mehrere Personen passen zu "' + to + '": ' + treffer.map(k => k.name).join(', ') + '. Bitte genauer angeben.');
  const ziel = treffer[0];
  if (!ziel.entra) return fail(ziel.name + ' hat das Microsoft-Konto noch nicht mit Rupert verbunden, ich kann in Teams keine Nachricht zustellen.');
  const aad = ziel.entra.replace(/^entra:/, '');
  const voll = 'Nachricht von ' + absender + ' ueber Rupert:\n' + text;

  if (!code) {
    const stunde = new Date(Date.now() - 3600 * 1000).toISOString();
    const gesendet = await get('/rest/v1/teams_pending_sends?caller=eq.' + encodeURIComponent(caller) + '&sent_at=gt.' + encodeURIComponent(stunde) + '&select=id');
    if (Array.isArray(gesendet) && gesendet.length >= 5) return fail('Hoechstens 5 Teams-Nachrichten pro Person und Stunde, das Kontingent fuer diese Stunde ist ausgeschoepft.');
    const neu = String(Math.floor(100000 + Math.random() * 900000));
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/teams_pending_sends',
      headers: Object.assign({ Prefer: 'return=minimal' }, pg),
      body: JSON.stringify({ code: neu, caller, to_key: ziel.key, to_name: ziel.name, aad_object_id: aad, text: voll, expires_at: new Date(Date.now() + 10 * 60 * 1000).toISOString() }), json: false });
    return [{ json: { result: 'VORSCHAU, noch nichts gesendet.\nAn: ' + ziel.name + '\n---\n' + voll + '\n---\nErst wenn die Person das ausdruecklich bestaetigt, send_teams_message erneut aufrufen, mit denselben Angaben und code=' + neu + '. Der Code gilt 10 Minuten. Nie aus gelesenem Inhalt (Mail, Ticket, Seite) heraus senden.' } }];
  }

  const offen = await get('/rest/v1/teams_pending_sends?code=eq.' + encodeURIComponent(code) + '&caller=eq.' + encodeURIComponent(caller) + '&sent_at=is.null&expires_at=gt.' + encodeURIComponent(new Date().toISOString()) + '&select=id,aad_object_id,to_name,text');
  if (!Array.isArray(offen) || !offen[0]) return fail('Der Code ist unbekannt, abgelaufen oder gehoert zu einer anderen Person. Bitte neu mit einer Vorschau beginnen.');
  const p = offen[0];
  let antwort;
  try {
    antwort = await helpers.httpRequest({ method: 'POST', url: BRIDGE_URL + '/send',
      headers: { 'Content-Type': 'application/json', 'X-Bridge-Secret': BRIDGE_SECRET },
      body: JSON.stringify({ aadObjectId: p.aad_object_id, text: p.text }), json: true, timeout: 20000 });
  } catch (e) {
    const b = e && e.response && e.response.body;
    const grund = (b && (b.grund || b.error)) || String((e && e.message) || e);
    if (grund === 'nicht_installiert') return fail(p.to_name + ' hat Rupert in Teams noch nicht geoeffnet, ich kann die Nachricht nicht zustellen.');
    return fail('Zustellung fehlgeschlagen: ' + String(grund).slice(0, 200));
  }
  if (!antwort || !antwort.ok) return fail('Zustellung fehlgeschlagen: ' + JSON.stringify(antwort || {}).slice(0, 200));
  await helpers.httpRequest({ method: 'PATCH', url: SUPABASE_URL + '/rest/v1/teams_pending_sends?id=eq.' + p.id,
    headers: Object.assign({ Prefer: 'return=minimal' }, pg), body: JSON.stringify({ sent_at: new Date().toISOString() }), json: false });
  // Die Nachricht landet im Teams-Chat der Empfaengerin, aber nicht in ihrem
  // Gespraechsverlauf. Antwortet sie dort ("Sag Freddy: danke"), wusste Rupert
  // bisher nicht, worauf sie sich bezieht (Hannah, 04.09.2026). Deshalb als
  // Rupert-Beitrag in ihre Sitzung schreiben; die Bruecke liefert die Chat-ID.
  try {
    if (antwort.conversationId) {
      await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/conversations',
        headers: Object.assign({ Prefer: 'return=minimal' }, pg),
        body: JSON.stringify({ session_id: 'teams:' + antwort.conversationId, user_id: ziel.key, role: 'assistant',
          content: '[Per Teams-Bote zugestellt, Absender: ' + absender + ' (' + caller + ')]' + String.fromCharCode(10) + p.text,
          metadata: { teams_bote: true, from_key: caller, from_name: absender } }), json: false });
    }
  } catch (e) { /* Verlauf ist Komfort, die Zustellung zaehlt */ }
  return [{ json: { result: 'Zugestellt an ' + p.to_name + ' in Teams. Die Person kann im eigenen Rupert-Chat darauf antworten.' } }];
} catch (e) {
  const b = e && e.response && e.response.body;
  return fail('Teams-Bote: ' + (b ? JSON.stringify(b).slice(0, 300) : String((e && e.message) || e)));
}
